const applicationExamples={showers:'wall-glass-hinge',partitions:'door-slider-fixed-panel',doors:'door-slider-fixed-panel',stairs:'railing-standoff',canopies:'canopy-support-rod'};
const legacyExamples={'hardware-hinge':'wall-glass-hinge','hardware-handle':'pull-handle','hardware-clamp':'wall-glass-connector','hardware-slider':'corner-shower-slider','hardware-profile':'glass-u-profile','hardware-seal':'glass-edge-seal','hardware-standoff':'railing-standoff','hardware-handrail':'wood-glass-handrail','hardware-wood-handrail':'wood-glass-handrail','hardware-canopy':'canopy-support-rod','hardware-shower-stabilizer':'shower-support-bar','hardware-floor-clamp':'floor-glass-clamp'};
const get=(object,key)=>Object.hasOwn(object,key)?object[key]:null;
export function realHardwareMediaForNode(input,finish=''){
 const node=typeof input==='string'?{image:input}:input||{};
 const own=get(hardwareRealAssets,String(node.id||''));
 const child=node.children?.find(x=>get(hardwareRealAssets,String(x.id||'')));
 const reference=child?.id||get(applicationExamples,String(node.id||''))||get(legacyExamples,String(node.image||node.imageKey||''));
 const terminal=node.kind==='hardware'||String(node.path||'').startsWith('/hardware/item/');
 const record=own||(terminal?null:get(hardwareRealAssets,String(reference||'')));
 if(!record)return {key:'hardware-unavailable',src:'',thumbnail:'',width:0,height:0,alt:'Фотография элемента уточняется',caption:'Фотография этого элемента уточняется. Подберём его вместе с конструкцией.',kind:'unavailable',photoFinishId:'',selectedFinish:finish,exactFinish:false,limitation:'Фотография этого элемента уточняется.'};
 const requested=finish||node.selectedFinish||record.defaultFinish;
 const selected=get(record.finishes,requested);
 const photo=selected||get(record.finishes,record.defaultFinish)||Object.values(record.finishes)[0];
 const photoLabel=get(finishLabels,photo.photoFinishId)||'Отделка на фото';
 const exact=Boolean(own&&selected&&record.verifiedFinishIds.includes(requested)&&photo.photoFinishId===requested);
 const title=own?node.title||record.title:record.title;
 const caption=exact?`${record.catalogueLabel||'Изображение из каталога'}. Отделка: ${photoLabel}.`:`На фото: ${title.toLowerCase()}, ${photoLabel.toLowerCase()}. ${own?'Изображение выбранной отделки уточняется; фотография не перекрашивается.':'Пример элемента этого раздела.'}`;
 return {...photo,key:'real-'+(own?node.id:reference)+'-'+photo.photoFinishId,thumbnail:photo.src,alt:`${title} — ${photoLabel.toLowerCase()}`,caption,kind:record.kind||'catalog-photo',photoFinishId:photo.photoFinishId,selectedFinish:requested,exactFinish:exact,limitation:exact?'':caption};
}
